function polylineIntersect(polyline, polygon, inOrOut) {
	var inside = [];
	var outside = [];
	var isPoints = [];
	var start = 0;
	for (i = 1; i < polyline.length; i++) {
		for (j = 1; j < polygon.length; j++) {
			var intersect = findIntersectionPoint(
				polyline[i - 1],
				polyline[i],
				polygon[j - 1],
				polygon[j]
			);
			if (intersect != null) {
				isPoints.push({
					x: intersect.x,
					y: intersect.y,
					sl: i
				});
			}
		}
	}
	var inPolygon = pointIn(polyline[0], polygon);
	var poly = [];
	if (isPoints.length != 0) {
		for (k = 0; k < isPoints.length; k++) {
			poly = [];
			if (k != 0) {
				poly.push({
					x: isPoints[k - 1].x,
					y: isPoints[k - 1].y
				});
			}
			for (l = start; l < isPoints[k].sl; l++) {
				poly.push({
					x: polyline[l].x,
					y: polyline[l].y
				});
			}
			poly.push({
				x: isPoints[k].x,
				y: isPoints[k].y
			});

			if (inPolygon) {
				inside.push(poly);
			} else {
				outside.push(poly);
			}
			inPolygon = !inPolygon;
			start = isPoints[k].sl;
		}
		poly = [];
		poly.push({
			x: isPoints[isPoints.length - 1].x,
			y: isPoints[isPoints.length - 1].y,
		});
	}
	for (m = start; m < polyline.length; m++) {
		poly.push({
			x: polyline[m].x,
			y: polyline[m].y
		});
	}

	if (inPolygon) {
		inside.push(poly);
	} else {
		outside.push(poly);
	}
	if (inOrOut == "in") {
		return inside;
	} else if (inOrOut == "out") {
		return outside;
	}

}

function findIntersectionPoint(p1, p2, p3, p4) {
	const denominator = (p4.y - p3.y) * (p2.x - p1.x) - (p4.x - p3.x) * (p2.y - p1.y);
	if (denominator === 0) {
		return null;
	}

	const ua = ((p4.x - p3.x) * (p1.y - p3.y) - (p4.y - p3.y) * (p1.x - p3.x)) / denominator;
	const ub = ((p2.x - p1.x) * (p1.y - p3.y) - (p2.y - p1.y) * (p1.x - p3.x)) / denominator;

	if (ua < 0 || ua > 1 || ub < 0 || ub > 1) {
		return null;
	}

	const intersectionX = p1.x + ua * (p2.x - p1.x);
	const intersectionY = p1.y + ua * (p2.y - p1.y);

	return {
		x: intersectionX,
		y: intersectionY
	};
}


function pointIn(punt, polygon) {
	var n = polygon.length,
		is_in = false,
		x = punt.x,
		y = punt.y,
		x1,
		x2,
		y1,
		y2;

	for (var i = 0; i < n - 1; ++i) {
		x1 = polygon[i].x;
		x2 = polygon[i + 1].x;
		y1 = polygon[i].y;
		y2 = polygon[i + 1].y;

		if (y < y1 != y < y2 && x < ((x2 - x1) * (y - y1)) / (y2 - y1) + x1) {
			is_in = !is_in;
		}
	}

	return is_in;
}


function isPointOnLine(x1, y1, x2, y2, px, py) {
	var dx = x2 - x1;
	var dy = y2 - y1;
	var d = Math.abs(dy * px - dx * py - x1 * y2 + x2 * y1) / Math.sqrt(Math.pow(dx, 2) + Math.pow(dy, 2));
	return d < 0.5; // tolerance value
}

