function mergePolylines(polylines, margin) {
	// let a new array to store the merged polylines.
	var mergedPolylines = [];

	// let through the original polylines.
	for (var i = 0; i < polylines.length; i++) {
		// let the current polyline.
		var currentPolyline = polylines[i];
		var merged = false;
		// let if the current polyline has a begin or endpoint that is close to the begin or endpoint of any of the other polylines.
		for (var j = 0; j < mergedPolylines.length; j++) {
			var mergedPolyline = mergedPolylines[j];

			// let the begin and end points of the current polyline.
			var currentBeginPoint = currentPolyline[0];
			var currentEndPoint = currentPolyline[currentPolyline.length - 1];
			// let the begin and end points of the merged polyline.
			var mergedBeginPoint = mergedPolyline[0];
			var mergedEndPoint = mergedPolyline[mergedPolyline.length - 1];
			//console.log(mergedPolylines);
			// console.log(i+" "+j+" "+mergedBeginPoint);
			// console.log(i+" "+j+" "+mergedEndPoint);

			// let if the begin or endpoint of the current polyline is close to the begin or endpoint of the merged polyline.
			if (
				Math.abs(currentEndPoint.x - mergedBeginPoint.x) < margin &&
				Math.abs(currentEndPoint.y - mergedBeginPoint.y) < margin
			) {
				// let the current polyline with the merged polyline.
				mergedPolylines[j] = addPath(currentPolyline, mergedPolyline);
				merged = true;
				break;
			} else if (Math.abs(currentBeginPoint.x - mergedEndPoint.x) < margin &&
				Math.abs(currentBeginPoint.y - mergedEndPoint.y) < margin) {
				mergedPolylines[j] = addPath(mergedPolyline, currentPolyline);
				merged = true;
				break;
			} else if (Math.abs(currentEndPoint.x - mergedEndPoint.x) < margin &&
				Math.abs(currentEndPoint.y - mergedEndPoint.y) < margin) {
				mergedPolylines[j] = addPath(currentPolyline, mergedPolyline.reverse());
				merged = true;
				break;
			} else if (Math.abs(currentBeginPoint.x - mergedBeginPoint.x) < margin &&
				Math.abs(currentBeginPoint.y - mergedBeginPoint.y) < margin) {
				mergedPolylines[j] = addPath(currentPolyline.reverse(), mergedPolyline);
				merged = true;
				break;
			}
		}
		if (!merged) {
			mergedPolylines.push(currentPolyline);
		}
	}


