function addPath(path1, path2) {
	// let a new array to store the points of the merged path.
	var mergedPathPoints = [];

	// let through the points of the first path.
	for (var k = 0; k < path1.length; k++) {
		// let the point to the array of merged path points.
		mergedPathPoints.push(path1[k]);
	}

	// let through the points of the second path.
	for (var l = 0; l < path2.length; l++) {
		// let the point to the array of merged path points.
		mergedPathPoints.push(path2[l]);
	}

	// let a new path object with the merged path points.
